begin;
create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','secretary','coach','guardian','student');
create table public.schools (id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 2 and 120), created_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users on delete cascade, full_name text not null default '', created_at timestamptz not null default now());
create table public.school_memberships (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, user_id uuid not null references public.profiles, role public.app_role not null, active boolean not null default true, created_at timestamptz not null default now(), unique(school_id,user_id));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
insert into public.profiles(id) select id from auth.users on conflict do nothing;
create function public.has_role(sid uuid, allowed public.app_role[]) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.school_memberships where school_id=sid and user_id=(select auth.uid()) and active and role=any(allowed)) $$;
create function public.is_member(sid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.school_memberships where school_id=sid and user_id=(select auth.uid()) and active) $$;

create table public.units (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, name text not null, address text, active boolean not null default true, created_at timestamptz not null default now(), unique(school_id,id));
create table public.categories (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, name text not null, min_age int check(min_age>=0), max_age int check(max_age>=min_age), active boolean not null default true, created_at timestamptz not null default now(), unique(school_id,id), unique(school_id,name));
create table public.coaches (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, user_id uuid references public.profiles, name text not null, email text, phone text, qualifications text, active boolean not null default true, created_at timestamptz not null default now(), unique(school_id,id), unique(school_id,user_id));
create table public.teams (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, name text not null, category_id uuid, coach_id uuid, unit_id uuid, location text, schedule text, capacity int not null default 20 check(capacity between 1 and 500), active boolean not null default true, created_at timestamptz not null default now(), unique(school_id,id), foreign key(school_id,category_id) references public.categories(school_id,id), foreign key(school_id,coach_id) references public.coaches(school_id,id), foreign key(school_id,unit_id) references public.units(school_id,id));
create table public.students (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, name text not null check(length(trim(name))>=2), registration_code text not null default upper(substr(gen_random_uuid()::text,1,8)), birth_date date not null check(birth_date<=current_date), phone text, address text, position text, shirt_number int check(shirt_number between 0 and 99), status text not null default 'active' check(status in ('active','inactive')), joined_on date not null default current_date, image_consent boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(school_id,id), unique(school_id,registration_code));
create table public.guardians (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, user_id uuid references public.profiles, name text not null, email text not null, phone text, address text, asaas_customer_id text, active boolean not null default true, created_at timestamptz not null default now(), unique(school_id,id), unique(school_id,email));
create table public.student_guardians (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, student_id uuid not null, guardian_id uuid not null, relationship text not null default 'Responsável', billing boolean not null default false, pickup boolean not null default false, emergency boolean not null default false, created_at timestamptz not null default now(), foreign key(school_id,student_id) references public.students(school_id,id), foreign key(school_id,guardian_id) references public.guardians(school_id,id), unique(school_id,student_id,guardian_id));
create table public.enrollments (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, student_id uuid not null, team_id uuid not null, status text not null default 'active' check(status in ('active','inactive')), started_on date not null default current_date, ended_on date, created_at timestamptz not null default now(), foreign key(school_id,student_id) references public.students(school_id,id), foreign key(school_id,team_id) references public.teams(school_id,id));
create unique index enrollment_active_unique on public.enrollments(school_id,student_id,team_id) where status='active';
create function public.enforce_capacity() returns trigger language plpgsql security definer set search_path='' as $$ declare lim int; enrolled int; begin if new.status='active' then select capacity into lim from public.teams where id=new.team_id and school_id=new.school_id for update; select count(*) into enrolled from public.enrollments where team_id=new.team_id and school_id=new.school_id and status='active' and id<>new.id; if enrolled>=lim then raise exception 'A turma está sem vagas.'; end if; end if; return new; end $$;
create trigger capacity_guard before insert or update on public.enrollments for each row execute function public.enforce_capacity();
create function public.can_coach(sid uuid,tid uuid) returns boolean language sql stable security definer set search_path='' as $$ select public.has_role(sid,array['coach']::public.app_role[]) and exists(select 1 from public.teams t join public.coaches c on c.id=t.coach_id and c.school_id=t.school_id where t.id=tid and t.school_id=sid and c.user_id=(select auth.uid()) and c.active) $$;
create function public.is_guardian(sid uuid,stid uuid,financial boolean default false) returns boolean language sql stable security definer set search_path='' as $$ select public.has_role(sid,array['guardian']::public.app_role[]) and exists(select 1 from public.student_guardians sg join public.guardians g on g.id=sg.guardian_id and g.school_id=sg.school_id where sg.school_id=sid and sg.student_id=stid and g.user_id=(select auth.uid()) and g.active and (not financial or sg.billing)) $$;
create function public.can_student(sid uuid,stid uuid) returns boolean language sql stable security definer set search_path='' as $$ select public.has_role(sid,array['admin','secretary']::public.app_role[]) or public.is_guardian(sid,stid) or exists(select 1 from public.enrollments e where e.school_id=sid and e.student_id=stid and e.status='active' and public.can_coach(sid,e.team_id)) $$;
create function public.can_team(sid uuid,tid uuid) returns boolean language sql stable security definer set search_path='' as $$ select public.has_role(sid,array['admin','secretary']::public.app_role[]) or public.can_coach(sid,tid) or exists(select 1 from public.enrollments e where e.school_id=sid and e.team_id=tid and e.status='active' and public.is_guardian(sid,e.student_id)) $$;
create table public.training_sessions (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, team_id uuid not null, name text not null, starts_at timestamptz not null, ends_at timestamptz not null check(ends_at>starts_at), location text, status text not null default 'scheduled' check(status in ('scheduled','completed','cancelled')), created_at timestamptz not null default now(), unique(school_id,id), foreign key(school_id,team_id) references public.teams(school_id,id), unique(school_id,team_id,starts_at));
create table public.attendance (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, session_id uuid not null, student_id uuid not null, status text not null check(status in ('present','absent','excused','late')), notes text, created_at timestamptz not null default now(), foreign key(school_id,session_id) references public.training_sessions(school_id,id), foreign key(school_id,student_id) references public.students(school_id,id), unique(school_id,session_id,student_id));
create function public.valid_attendance() returns trigger language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from public.training_sessions s join public.enrollments e on e.team_id=s.team_id and e.school_id=s.school_id where s.id=new.session_id and s.school_id=new.school_id and e.student_id=new.student_id and e.started_on <= (s.starts_at at time zone 'America/Sao_Paulo')::date and (e.ended_on is null or e.ended_on >= (s.starts_at at time zone 'America/Sao_Paulo')::date)) then raise exception 'Aluno não matriculado nesta turma na data do treino.'; end if; return new; end $$;
create trigger attendance_enrollment before insert or update on public.attendance for each row execute function public.valid_attendance();
create table public.plans (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, name text not null, amount numeric(12,2) not null check(amount>=0), interval_months int not null default 1 check(interval_months between 1 and 12), due_day int not null default 10 check(due_day between 1 and 28), active boolean not null default true, created_at timestamptz not null default now(), unique(school_id,id));
create table public.student_plans (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, student_id uuid not null, plan_id uuid not null, discount numeric(12,2) not null default 0 check(discount>=0), started_on date not null default current_date, ended_on date, created_at timestamptz not null default now(), foreign key(school_id,student_id) references public.students(school_id,id), foreign key(school_id,plan_id) references public.plans(school_id,id));
create table public.invoices (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, student_id uuid not null, guardian_id uuid not null, plan_id uuid, name text not null, competence date not null, original_amount numeric(12,2) not null check(original_amount>=0), discount numeric(12,2) not null default 0 check(discount>=0 and discount<=original_amount), fee numeric(12,2) not null default 0 check(fee>=0), amount numeric(12,2) generated always as (original_amount-discount+fee) stored, due_date date not null, paid_at timestamptz, status text not null default 'pending' check(status in ('pending','processing','paid','overdue','cancelled','refunded')), billing_type text not null default 'PIX' check(billing_type in ('PIX','BOLETO')), provider_id text unique, provider_url text, created_at timestamptz not null default now(), unique(school_id,id), unique(school_id,student_id,competence), foreign key(school_id,student_id) references public.students(school_id,id), foreign key(school_id,guardian_id) references public.guardians(school_id,id), foreign key(school_id,plan_id) references public.plans(school_id,id));
create function public.validate_invoice() returns trigger language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from public.student_guardians where school_id=new.school_id and student_id=new.student_id and guardian_id=new.guardian_id and billing) then raise exception 'Vincule um responsável financeiro ao aluno antes de gerar a mensalidade.'; end if; if current_user in ('anon','authenticated') or current_setting('role',true)='authenticated' then if tg_op='INSERT' and (new.status<>'pending' or new.provider_id is not null or new.paid_at is not null or new.provider_url is not null) then raise exception 'Estado de pagamento reservado à integração.'; end if; if tg_op='UPDATE' and (new.status is distinct from old.status or new.provider_id is distinct from old.provider_id or new.provider_url is distinct from old.provider_url or new.paid_at is distinct from old.paid_at or old.provider_id is not null) then raise exception 'Cobrança integrada só pode ser alterada pelo backend.'; end if; end if; return new; end $$;
create trigger invoice_guard before insert or update on public.invoices for each row execute function public.validate_invoice();
create table public.payments (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, invoice_id uuid not null, provider_id text not null unique, amount numeric(12,2) not null check(amount>=0), paid_at timestamptz not null, created_at timestamptz not null default now(), foreign key(school_id,invoice_id) references public.invoices(school_id,id));
create table public.payment_events (id text primary key, school_id uuid not null references public.schools, invoice_id uuid not null, event_type text not null, processed_at timestamptz not null default now(), foreign key(school_id,invoice_id) references public.invoices(school_id,id));
create table public.announcements (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, name text not null, content text not null, team_id uuid, published boolean not null default false, publish_at timestamptz not null default now(), created_at timestamptz not null default now(), foreign key(school_id,team_id) references public.teams(school_id,id));
create table public.news (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, name text not null, summary text, content text not null, category text not null default 'Notícias gerais', published boolean not null default false, publish_at timestamptz not null default now(), created_at timestamptz not null default now());
create table public.events (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, name text not null, description text, kind text not null default 'Evento', team_id uuid, starts_at timestamptz not null, ends_at timestamptz not null check(ends_at>starts_at), location text, status text not null default 'scheduled' check(status in ('scheduled','cancelled','completed')), created_at timestamptz not null default now(), foreign key(school_id,team_id) references public.teams(school_id,id));
create table public.competitions (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, name text not null, location text, starts_on date not null, ends_on date check(ends_on>=starts_on), created_at timestamptz not null default now(), unique(school_id,id));
create table public.matches (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, name text not null, competition_id uuid, team_id uuid not null, opponent text not null, starts_at timestamptz not null, location text, home_score int check(home_score>=0), away_score int check(away_score>=0), created_at timestamptz not null default now(), unique(school_id,id), foreign key(school_id,team_id) references public.teams(school_id,id), foreign key(school_id,competition_id) references public.competitions(school_id,id));
create table public.callups (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, match_id uuid not null, student_id uuid not null, confirmed boolean, created_at timestamptz not null default now(), foreign key(school_id,match_id) references public.matches(school_id,id), foreign key(school_id,student_id) references public.students(school_id,id), unique(school_id,match_id,student_id));
create table public.evaluation_criteria (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, name text not null, max_score numeric not null default 10 check(max_score>0), active boolean not null default true, created_at timestamptz not null default now(), unique(school_id,id));
create table public.evaluations (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, student_id uuid not null, criterion_id uuid not null, team_id uuid not null, name text not null, score numeric not null check(score>=0), evaluated_on date not null default current_date, comments text, shared boolean not null default false, created_at timestamptz not null default now(), foreign key(school_id,student_id) references public.students(school_id,id), foreign key(school_id,criterion_id) references public.evaluation_criteria(school_id,id), foreign key(school_id,team_id) references public.teams(school_id,id));
create function public.valid_evaluation() returns trigger language plpgsql security definer set search_path='' as $$ declare lim numeric; begin select max_score into lim from public.evaluation_criteria where school_id=new.school_id and id=new.criterion_id; if new.score>lim then raise exception 'Nota acima da escala do critério.'; end if; if not exists(select 1 from public.enrollments where school_id=new.school_id and student_id=new.student_id and team_id=new.team_id and status='active') then raise exception 'Aluno não matriculado nesta turma.'; end if; return new; end $$;
create trigger evaluation_guard before insert or update on public.evaluations for each row execute function public.valid_evaluation();
create table public.documents (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, student_id uuid not null, name text not null, storage_path text not null unique, created_at timestamptz not null default now(), foreign key(school_id,student_id) references public.students(school_id,id), check(storage_path like school_id::text||'/'||student_id::text||'/%'));
create table public.notifications (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, user_id uuid not null references public.profiles, name text not null, content text, read_at timestamptz, created_at timestamptz not null default now());
create table public.notification_preferences (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, user_id uuid not null references public.profiles, email_enabled boolean not null default true, push_enabled boolean not null default false, created_at timestamptz not null default now(), unique(school_id,user_id));
create table public.school_settings (id uuid primary key default gen_random_uuid(), school_id uuid not null unique references public.schools, name text not null default 'Configurações', timezone text not null default 'America/Sao_Paulo' check(timezone='America/Sao_Paulo'), contact_email text, created_at timestamptz not null default now());
create table public.audit_logs (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools, actor_id uuid, entity text not null, record_id uuid not null, operation text not null, created_at timestamptz not null default now());
create function public.audit_change() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.audit_logs(school_id,actor_id,entity,record_id,operation) values(new.school_id,auth.uid(),tg_table_name,new.id,tg_op); return new; end $$;
do $$ declare t text; begin foreach t in array array['students','guardians','student_guardians','coaches','categories','teams','units','enrollments','training_sessions','attendance','plans','student_plans','invoices','news','announcements','events','evaluations','evaluation_criteria','documents','competitions','matches','callups','school_settings'] loop execute format('create trigger audit_record after insert or update on public.%I for each row execute function public.audit_change()',t); end loop; end $$;

-- Nenhuma tabela de negócio permite DELETE pelo navegador. Arquivamento preserva histórico.
alter table public.schools enable row level security;
alter table public.profiles enable row level security;
alter table public.school_memberships enable row level security;
create policy school_read on public.schools for select to authenticated using(public.is_member(id));
create policy profile_self on public.profiles for select to authenticated using(id=auth.uid());
create policy membership_read on public.school_memberships for select to authenticated using(user_id=auth.uid() or public.has_role(school_id,array['admin']::public.app_role[]));
do $$ declare t text; begin foreach t in array array['units','categories','coaches','teams','students','guardians','student_guardians','enrollments','training_sessions','attendance','plans','student_plans','invoices','payments','payment_events','news','announcements','events','competitions','matches','callups','evaluation_criteria','evaluations','documents','notifications','notification_preferences','audit_logs','school_settings'] loop execute format('alter table public.%I enable row level security',t); execute format('create index on public.%I(school_id)',t); end loop; end $$;
do $$ declare t text; begin foreach t in array array['units','categories','plans','evaluation_criteria'] loop execute format('create policy read_rows on public.%I for select to authenticated using(public.is_member(school_id))',t); end loop; foreach t in array array['units','categories','coaches','teams','students','guardians','student_guardians','enrollments','training_sessions','plans','student_plans','invoices','news','announcements','events','competitions','matches','callups','evaluation_criteria','evaluations','documents'] loop execute format('create policy staff_insert on public.%I for insert to authenticated with check(public.has_role(school_id,array[''admin'',''secretary'']::public.app_role[]))',t); execute format('create policy staff_update on public.%I for update to authenticated using(public.has_role(school_id,array[''admin'',''secretary'']::public.app_role[])) with check(public.has_role(school_id,array[''admin'',''secretary'']::public.app_role[]))',t); end loop; end $$;
create policy students_read on public.students for select to authenticated using(public.can_student(school_id,id));
create policy teams_read on public.teams for select to authenticated using(public.can_team(school_id,id));
create policy coaches_read on public.coaches for select to authenticated using(public.has_role(school_id,array['admin','secretary']::public.app_role[]) or user_id=auth.uid());
create policy guardians_read on public.guardians for select to authenticated using(public.has_role(school_id,array['admin','secretary']::public.app_role[]) or (public.is_member(school_id) and user_id=auth.uid()));
create policy guardian_links_read on public.student_guardians for select to authenticated using(public.has_role(school_id,array['admin','secretary']::public.app_role[]) or exists(select 1 from public.guardians g where g.id=guardian_id and g.school_id=student_guardians.school_id and g.user_id=auth.uid()));
create policy enrollments_read on public.enrollments for select to authenticated using(public.has_role(school_id,array['admin','secretary']::public.app_role[]) or public.is_guardian(school_id,student_id) or public.can_coach(school_id,team_id));
create policy training_read on public.training_sessions for select to authenticated using(public.can_team(school_id,team_id));
create policy training_insert_coach on public.training_sessions for insert to authenticated with check(public.can_coach(school_id,team_id));
create policy training_update_coach on public.training_sessions for update to authenticated using(public.can_coach(school_id,team_id)) with check(public.can_coach(school_id,team_id));
create policy attendance_read on public.attendance for select to authenticated using(public.has_role(school_id,array['admin','secretary']::public.app_role[]) or public.is_guardian(school_id,student_id) or exists(select 1 from public.training_sessions s where s.id=session_id and s.school_id=attendance.school_id and public.can_coach(s.school_id,s.team_id)));
create policy attendance_insert on public.attendance for insert to authenticated with check(public.has_role(school_id,array['admin','secretary']::public.app_role[]) or exists(select 1 from public.training_sessions s where s.id=session_id and s.school_id=attendance.school_id and public.can_coach(s.school_id,s.team_id)));
create policy attendance_update on public.attendance for update to authenticated using(public.has_role(school_id,array['admin','secretary']::public.app_role[]) or exists(select 1 from public.training_sessions s where s.id=session_id and s.school_id=attendance.school_id and public.can_coach(s.school_id,s.team_id))) with check(public.has_role(school_id,array['admin','secretary']::public.app_role[]) or exists(select 1 from public.training_sessions s where s.id=session_id and s.school_id=attendance.school_id and public.can_coach(s.school_id,s.team_id)));
create policy student_plan_read on public.student_plans for select to authenticated using(public.has_role(school_id,array['admin','secretary']::public.app_role[]) or public.is_guardian(school_id,student_id,true));
create policy invoice_read on public.invoices for select to authenticated using(public.has_role(school_id,array['admin','secretary']::public.app_role[]) or (public.is_guardian(school_id,student_id,true) and exists(select 1 from public.guardians g where g.id=guardian_id and g.user_id=auth.uid())));
create policy payments_read on public.payments for select to authenticated using(exists(select 1 from public.invoices i where i.id=invoice_id and i.school_id=payments.school_id));
create policy payment_event_staff on public.payment_events for select to authenticated using(public.has_role(school_id,array['admin']::public.app_role[]));
create policy news_read on public.news for select to authenticated using(public.has_role(school_id,array['admin','secretary']::public.app_role[]) or (public.is_member(school_id) and published and publish_at<=now()));
create policy announcements_read on public.announcements for select to authenticated using(public.has_role(school_id,array['admin','secretary']::public.app_role[]) or (public.is_member(school_id) and published and publish_at<=now() and (team_id is null or public.can_team(school_id,team_id))));
create policy events_read on public.events for select to authenticated using(public.has_role(school_id,array['admin','secretary']::public.app_role[]) or (public.is_member(school_id) and (team_id is null or public.can_team(school_id,team_id))));
create policy competitions_read on public.competitions for select to authenticated using(public.is_member(school_id));
create policy matches_read on public.matches for select to authenticated using(public.can_team(school_id,team_id));
create policy callups_read on public.callups for select to authenticated using(public.can_student(school_id,student_id));
create policy criteria_evaluations_read on public.evaluations for select to authenticated using(public.has_role(school_id,array['admin','secretary']::public.app_role[]) or public.can_coach(school_id,team_id) or (shared and public.is_guardian(school_id,student_id)));
create policy eval_coach_insert on public.evaluations for insert to authenticated with check(public.can_coach(school_id,team_id));
create policy eval_coach_update on public.evaluations for update to authenticated using(public.can_coach(school_id,team_id)) with check(public.can_coach(school_id,team_id));
create policy documents_read on public.documents for select to authenticated using(public.has_role(school_id,array['admin','secretary']::public.app_role[]) or public.is_guardian(school_id,student_id));
create policy notifications_read on public.notifications for select to authenticated using(public.is_member(school_id) and user_id=auth.uid());
create policy notification_preferences_read on public.notification_preferences for select to authenticated using(public.is_member(school_id) and user_id=auth.uid());
create policy notification_preferences_insert on public.notification_preferences for insert to authenticated with check(public.is_member(school_id) and user_id=auth.uid());
create policy notification_preferences_update on public.notification_preferences for update to authenticated using(public.is_member(school_id) and user_id=auth.uid()) with check(public.is_member(school_id) and user_id=auth.uid());
create policy audit_admin_read on public.audit_logs for select to authenticated using(public.has_role(school_id,array['admin']::public.app_role[]));
create policy settings_admin_read on public.school_settings for select to authenticated using(public.has_role(school_id,array['admin']::public.app_role[]));
create policy settings_admin_insert on public.school_settings for insert to authenticated with check(public.has_role(school_id,array['admin']::public.app_role[]));
create policy settings_admin_update on public.school_settings for update to authenticated using(public.has_role(school_id,array['admin']::public.app_role[])) with check(public.has_role(school_id,array['admin']::public.app_role[]));

create function public.mark_notification_read(nid uuid) returns void language sql security invoker set search_path='' as $$ update public.notifications set read_at=now() where id=nid and user_id=auth.uid() $$;
create policy notifications_update on public.notifications for update to authenticated using(public.is_member(school_id) and user_id=auth.uid()) with check(public.is_member(school_id) and user_id=auth.uid());
revoke update on public.notifications from authenticated;
grant update(read_at) on public.notifications to authenticated;

-- Agregações executadas com RLS do solicitante e sobre todos os registros, não a página atual.
create function public.dashboard(sid uuid, from_date date, to_date date) returns jsonb language plpgsql security invoker set search_path='' as $$ declare result jsonb; begin
if not public.has_role(sid,array['admin','secretary','coach']::public.app_role[]) then raise exception 'Acesso não autorizado'; end if;
select jsonb_build_object(
'students',(select count(*) from public.students where school_id=sid),
'active',(select count(*) from public.students where school_id=sid and status='active'),
'new_students',(select count(*) from public.students where school_id=sid and joined_on between from_date and to_date),
'teams',(select count(*) from public.teams where school_id=sid and active),
'coaches',(select count(*) from public.coaches where school_id=sid and active),
'received',(select coalesce(sum(amount),0) from public.invoices where school_id=sid and status='paid' and (paid_at at time zone 'America/Sao_Paulo')::date between from_date and to_date),
'pending',(select coalesce(sum(amount),0) from public.invoices where school_id=sid and status in ('pending','processing','overdue') and due_date between from_date and to_date),
'overdue',(select coalesce(sum(amount),0) from public.invoices where school_id=sid and status in ('pending','processing','overdue') and due_date<current_date and due_date between from_date and to_date),
'attendance',(select coalesce(round(100.0*count(*) filter(where a.status in ('present','late'))/nullif(count(*) filter(where a.status<>'excused'),0),1),0) from public.attendance a join public.training_sessions s on s.id=a.session_id and s.school_id=a.school_id where a.school_id=sid and (s.starts_at at time zone 'America/Sao_Paulo')::date between from_date and to_date),
'revenue',(select coalesce(jsonb_agg(r order by r.month),'[]'::jsonb) from (select to_char(m,'YYYY-MM') as month,coalesce(sum(i.amount),0) as amount from generate_series(date_trunc('month',to_date::timestamp)-interval '11 months',date_trunc('month',to_date::timestamp),interval '1 month') m left join public.invoices i on i.school_id=sid and i.status='paid' and date_trunc('month',i.paid_at at time zone 'America/Sao_Paulo')=m group by m) r),
'categories',(select coalesce(jsonb_agg(c),'[]'::jsonb) from (select cat.name,count(distinct e.student_id) as value from public.categories cat left join public.teams t on t.category_id=cat.id and t.school_id=cat.school_id left join public.enrollments e on e.team_id=t.id and e.school_id=t.school_id and e.status='active' where cat.school_id=sid group by cat.id,cat.name) c)
) into result; return result; end $$;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('student-documents','student-documents',false,10485760,array['application/pdf','image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy private_document_read on storage.objects for select to authenticated using(bucket_id='student-documents' and exists(select 1 from public.documents d where d.storage_path=name));
create policy private_document_upload on storage.objects for insert to authenticated with check(bucket_id='student-documents' and exists(select 1 from public.students s where s.school_id::text=(storage.foldername(name))[1] and s.id::text=(storage.foldername(name))[2] and public.has_role(s.school_id,array['admin','secretary']::public.app_role[])));

-- Funções de gatilho não são APIs públicas.
revoke execute on function public.handle_new_user(), public.enforce_capacity(), public.valid_attendance(), public.validate_invoice(), public.valid_evaluation(), public.audit_change() from public,anon,authenticated;
revoke all on all tables in schema public from anon;
grant select on all tables in schema public to authenticated;
grant insert,update on public.units,public.categories,public.coaches,public.teams,public.students,public.guardians,public.student_guardians,public.enrollments,public.training_sessions,public.attendance,public.plans,public.student_plans,public.invoices,public.news,public.announcements,public.events,public.competitions,public.matches,public.callups,public.evaluation_criteria,public.evaluations,public.documents,public.school_settings,public.notification_preferences to authenticated;
revoke insert,update,delete on public.schools,public.profiles,public.school_memberships,public.payments,public.payment_events,public.audit_logs from authenticated;
commit;
